-- Business changes are part of the same transaction. Sensitive values are hashed.
DELIMITER $$
CREATE TRIGGER trace_users_insert AFTER INSERT ON users FOR EACH ROW BEGIN CALL sp_audit_change(NULL,'users',NEW.id,'INSERT',NULL,JSON_OBJECT('id',NEW.id,'name',NEW.name,'active',NEW.active,'clinical_domain',NEW.clinical_domain,'platform_role',NEW.platform_role,'email_verified',NEW.email_verified,'password_hash_sha256',SHA2(CAST(NEW.password_hash AS CHAR),256))); END$$
CREATE TRIGGER trace_users_update AFTER UPDATE ON users FOR EACH ROW BEGIN IF NOT (JSON_OBJECT('id',OLD.id,'name',OLD.name,'active',OLD.active,'clinical_domain',OLD.clinical_domain,'platform_role',OLD.platform_role,'email_verified',OLD.email_verified,'password_hash_sha256',SHA2(CAST(OLD.password_hash AS CHAR),256))<=>JSON_OBJECT('id',NEW.id,'name',NEW.name,'active',NEW.active,'clinical_domain',NEW.clinical_domain,'platform_role',NEW.platform_role,'email_verified',NEW.email_verified,'password_hash_sha256',SHA2(CAST(NEW.password_hash AS CHAR),256))) THEN CALL sp_audit_change(NULL,'users',NEW.id,'UPDATE',JSON_OBJECT('id',OLD.id,'name',OLD.name,'active',OLD.active,'clinical_domain',OLD.clinical_domain,'platform_role',OLD.platform_role,'email_verified',OLD.email_verified,'password_hash_sha256',SHA2(CAST(OLD.password_hash AS CHAR),256)),JSON_OBJECT('id',NEW.id,'name',NEW.name,'active',NEW.active,'clinical_domain',NEW.clinical_domain,'platform_role',NEW.platform_role,'email_verified',NEW.email_verified,'password_hash_sha256',SHA2(CAST(NEW.password_hash AS CHAR),256))); END IF; END$$
CREATE TRIGGER trace_users_delete AFTER DELETE ON users FOR EACH ROW BEGIN CALL sp_audit_change(NULL,'users',OLD.id,'DELETE',JSON_OBJECT('id',OLD.id,'name',OLD.name,'active',OLD.active,'clinical_domain',OLD.clinical_domain,'platform_role',OLD.platform_role,'email_verified',OLD.email_verified,'password_hash_sha256',SHA2(CAST(OLD.password_hash AS CHAR),256)),NULL); END$$
